class FastMCPApp(Provider):

    def __init__(self, name: str) -> None:
        super().__init__()
        self.name = name
        self._local = LocalProvider(on_duplicate='error')

    def __repr__(self) -> str:
        return f'FastMCPApp({self.name!r})'

    @overload
    def tool(self, name_or_fn: F, *, name: str | None=None, description: str | None=None, model: bool=False, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> F:
        ...

    @overload
    def tool(self, name_or_fn: str | None=None, *, name: str | None=None, description: str | None=None, model: bool=False, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> Callable[[F], F]:
        ...

    def tool(self, name_or_fn: str | AnyFunction | None=None, *, name: str | None=None, description: str | None=None, model: bool=False, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> Any:
        visibility: list[Literal['app', 'model']] = ['app', 'model'] if model else ['app']

        def _register(fn: F, tool_name: str | None) -> F:
            resolved_name = tool_name or getattr(fn, '__name__', None)
            if resolved_name is None:
                raise ValueError(f'Cannot determine tool name for {fn!r}')
            from fastmcp.apps.config import AppConfig, app_config_to_meta_dict
            from fastmcp.server.providers.addressing import hash_tool
            app_config = AppConfig(visibility=visibility)
            meta: dict[str, Any] = {'ui': app_config_to_meta_dict(app_config), 'fastmcp': {'app': self.name, '_tool_hash': hash_tool(self.name, resolved_name)}}
            tool_obj = Tool.from_function(fn, name=resolved_name, description=description, meta=meta, timeout=timeout, auth=auth)
            self._local._add_component(tool_obj)
            return fn
        return _dispatch_decorator(name_or_fn, name, _register, 'tool')

    @overload
    def ui(self, name_or_fn: F, *, name: str | None=None, description: str | None=None, title: str | None=None, tags: set[str] | None=None, icons: list[Icon] | None=None, annotations: ToolAnnotations | None=None, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> F:
        ...

    @overload
    def ui(self, name_or_fn: str | None=None, *, name: str | None=None, description: str | None=None, title: str | None=None, tags: set[str] | None=None, icons: list[Icon] | None=None, annotations: ToolAnnotations | None=None, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> Callable[[F], F]:
        ...

    def ui(self, name_or_fn: str | AnyFunction | None=None, *, name: str | None=None, description: str | None=None, title: str | None=None, tags: set[str] | None=None, icons: list[Icon] | None=None, annotations: ToolAnnotations | None=None, auth: AuthCheck | list[AuthCheck] | None=None, timeout: float | None=None) -> Any:

        def _register(fn: F, tool_name: str | None) -> F:
            from fastmcp.apps.config import AppConfig, app_config_to_meta_dict
            from fastmcp.server.providers.addressing import hash_tool
            from fastmcp.server.providers.local_provider.decorators.tools import PREFAB_RENDERER_URI
            resolved = tool_name or getattr(fn, '__name__', None) or 'unknown'
            app_config = AppConfig(resource_uri=PREFAB_RENDERER_URI, visibility=['model'])
            meta: dict[str, Any] = {'ui': app_config_to_meta_dict(app_config), 'fastmcp': {'app': self.name, '_tool_hash': hash_tool(self.name, resolved)}}
            tool_obj = Tool.from_function(fn, name=tool_name, description=description, title=title, tags=tags, icons=icons, annotations=annotations, meta=meta, timeout=timeout, auth=auth)
            self._local._add_component(tool_obj)
            return fn
        return _dispatch_decorator(name_or_fn, name, _register, 'ui')

    def add_tool(self, tool: Tool | Callable[..., Any]) -> Tool:
        if not isinstance(tool, Tool):
            tool = Tool._ensure_tool(tool)
        from fastmcp.server.providers.addressing import hash_tool
        meta = dict(tool.meta) if tool.meta else {}
        fm = meta.setdefault('fastmcp', {})
        fm['app'] = self.name
        fm['_tool_hash'] = hash_tool(self.name, tool.name)
        ui = meta.setdefault('ui', {})
        if 'visibility' not in ui:
            ui['visibility'] = ['app']
        tool.meta = meta
        self._local._add_component(tool)
        return tool

    async def _list_tools(self) -> Sequence[Tool]:
        return await self._local._list_tools()

    async def _get_tool(self, name: str, version: Any=None) -> Tool | None:
        return await self._local._get_tool(name, version)

    async def _list_resources(self) -> Sequence[Any]:
        return await self._local._list_resources()

    async def _get_resource(self, uri: str, version: Any=None) -> Any | None:
        return await self._local._get_resource(uri, version)

    async def _list_resource_templates(self) -> Sequence[Any]:
        return await self._local._list_resource_templates()

    async def _get_resource_template(self, uri: str, version: Any=None) -> Any | None:
        return await self._local._get_resource_template(uri, version)

    async def _list_prompts(self) -> Sequence[Any]:
        return await self._local._list_prompts()

    async def _get_prompt(self, name: str, version: Any=None) -> Any | None:
        return await self._local._get_prompt(name, version)

    @asynccontextmanager
    async def lifespan(self) -> AsyncIterator[None]:
        async with self._local.lifespan():
            yield

    def run(self, transport: Literal['stdio', 'http', 'sse', 'streamable-http'] | None=None, **kwargs: Any) -> None:
        from fastmcp.server.server import FastMCP
        server = FastMCP(self.name)
        server.add_provider(self)
        server.run(transport=transport, **kwargs)

# --- helper: fastmcp.apps.app._dispatch_decorator ---
def _dispatch_decorator(name_or_fn: str | AnyFunction | None, name: str | None, register: Callable[[Any, str | None], Any], decorator_name: str) -> Any:
    if inspect.isroutine(name_or_fn):
        return register(name_or_fn, name)
    if isinstance(name_or_fn, str):
        if name is not None:
            raise TypeError('Cannot specify both a name as first argument and as keyword argument.')
        tool_name: str | None = name_or_fn
    elif name_or_fn is None:
        tool_name = name
    else:
        raise TypeError(f'First argument to @{decorator_name} must be a function, string, or None, got {type(name_or_fn)}')

    def decorator(fn: F) -> F:
        return register(fn, tool_name)
    return decorator
